import{_ as t,o as e,c as n,a2 as p}from"./chunks/framework.A5mep7Fe.js";const q=JSON.parse('{"title":"🤖 Agent 岗真题（30+）","description":"","frontmatter":{},"headers":[],"relativePath":"面试真题集/Agent岗真题.md","filePath":"面试真题集/Agent岗真题.md","lastUpdated":1786806808000}'),r={name:"面试真题集/Agent岗真题.md"};function a(l,o,s,c,g,u){return e(),n("div",null,[...o[0]||(o[0]=[p('<h1 id="🤖-agent-岗真题-30" tabindex="-1">🤖 Agent 岗真题（30+） <a class="header-anchor" href="#🤖-agent-岗真题-30" aria-label="Permalink to &quot;🤖 Agent 岗真题（30+）&quot;">​</a></h1><blockquote><p>高频方向：Agent 架构、RAG、记忆、工具、MCP、多 Agent、工程化。覆盖算法应用 + 开发双视角。</p></blockquote><hr><h2 id="一、agent-范式" tabindex="-1">一、Agent 范式 <a class="header-anchor" href="#一、agent-范式" aria-label="Permalink to &quot;一、Agent 范式&quot;">​</a></h2><p><strong>1. 什么是 AI Agent？核心组成？</strong></p><blockquote><p>LLM（大脑）+ 规划 + 记忆 + 工具 + 反思。让模型能多步完成目标、调用外部。</p></blockquote><p><strong>2. ReAct 的工作循环？</strong></p><blockquote><p>Thought → Action → Observation 循环；每步基于观察动态决策，强交互。</p></blockquote><p><strong>3. 为什么选 ReAct 而不是 Plan-and-Execute？</strong></p><blockquote><p>实时/动态/工具调用 → ReAct；长链可规划任务 → Plan-and-Execute。常「Plan 打底+ReAct 执行+Reflexion 纠错」。</p></blockquote><p><strong>4. Reflexion 是什么？</strong></p><blockquote><p>执行后自我反思失败原因，写入记忆，下一轮改进；适合可验证/迭代任务（代码）。</p></blockquote><p><strong>5. Agent 最常见的失败场景？</strong></p><blockquote><p>循环打转、幻觉工具参数、长上下文遗忘。对策：步数限制、循环检测、记忆写入、校验节点。</p></blockquote><h2 id="二、rag" tabindex="-1">二、RAG <a class="header-anchor" href="#二、rag" aria-label="Permalink to &quot;二、RAG&quot;">​</a></h2><p><strong>6. RAG 解决什么痛点？</strong></p><blockquote><p>知识过时、易幻觉、不可溯源。生成前先检索，可更新可溯源。</p></blockquote><p><strong>7. RAG 标准流水线？</strong></p><blockquote><p>切片→嵌入→存向量库→query嵌入→检索→重排→拼接→生成。</p></blockquote><p><strong>8. 为什么需要重排（Rerank）？</strong></p><blockquote><p>初检 ANN 快但粗；Cross-Encoder 精排用少量候选换质量大升。</p></blockquote><p><strong>9. 混合检索为什么更好？</strong></p><blockquote><p>向量弱精确词、BM25 强精确匹配；RRF 融合互补，召回更佳。</p></blockquote><p><strong>10. RAG vs 微调怎么选？</strong></p><blockquote><p>私有/时效知识+溯源 → RAG；改行为/风格/能力 → 微调。常结合。</p></blockquote><p><strong>11. RAG 幻觉怎么治？</strong></p><blockquote><p>仅基于片段 + 出处 + 无检索拒答 + Faithfulness 评测。</p></blockquote><p><strong>12. 检索不准怎么优化？</strong></p><blockquote><p>切片/换 embedding/加 BM25/重排/query 改写/元数据过滤；先定位召回还是排序问题。</p></blockquote><h2 id="三、记忆与工具" tabindex="-1">三、记忆与工具 <a class="header-anchor" href="#三、记忆与工具" aria-label="Permalink to &quot;三、记忆与工具&quot;">​</a></h2><p><strong>13. 短期 vs 长期记忆？</strong></p><blockquote><p>短期：上下文窗口/滑窗；长期：向量库/摘要/结构化存储，跨会话持久。</p></blockquote><p><strong>14. Function Calling vs Tool Use？</strong></p><blockquote><p>FC：JSON Schema 标准、易实现；Tool Use：灵活、可并行、元数据多。简单用 FC，复杂用 Tool Use。</p></blockquote><p><strong>15. 如何优化工具选择准确性？</strong></p><blockquote><p>清晰工具描述/参数示例、few-shot、候选过滤、错误反馈学习。</p></blockquote><p><strong>16. 如何防御提示注入？</strong></p><blockquote><p>工具返回当不可信数据隔离、不执行其中指令、清洗、高危操作加权限/人工确认。</p></blockquote><p><strong>17. 工具调用失败怎么办？</strong></p><blockquote><p>重试+错误回灌模型自修正、备用工具、超时/资源限制、降级告知。</p></blockquote><h2 id="四、mcp-与多-agent" tabindex="-1">四、MCP 与多 Agent <a class="header-anchor" href="#四、mcp-与多-agent" aria-label="Permalink to &quot;四、MCP 与多 Agent&quot;">​</a></h2><p><strong>18. MCP 解决什么？</strong></p><blockquote><p>工具/数据源与 Agent 强耦合、无法复用；用标准协议解耦，一次开发多端复用。</p></blockquote><p><strong>19. 多 Agent 协作模式？</strong></p><blockquote><p>主管-下属、流水线、辩论评审、角色扮演；通信用消息/共享记忆。</p></blockquote><p><strong>20. 多 Agent 一定更好吗？</strong></p><blockquote><p>否。增成本复杂度，仅「需分工/并行/专业化」时收益明显；常先问单 Agent 能否解决。</p></blockquote><p><strong>21. 多 Agent 冲突怎么解？</strong></p><blockquote><p>主管仲裁、评审/投票、共享一致记忆、明确职责边界。</p></blockquote><h2 id="五、工程化与评估" tabindex="-1">五、工程化与评估 <a class="header-anchor" href="#五、工程化与评估" aria-label="Permalink to &quot;五、工程化与评估&quot;">​</a></h2><p><strong>22. Agent 上线最大坑？</strong></p><blockquote><p>不可控（长链路任一环失败/幻觉）、成本难预测、难评测。解法：降级+追踪+回归评测+成本监控。</p></blockquote><p><strong>23. 怎么做 Agent 回归测试？</strong></p><blockquote><p>固化任务集与期望轨迹/结果，每次改动跑回归；LLM-as-Judge 评质量；监控线上漂移。</p></blockquote><p><strong>24. 模型路由怎么设计？</strong></p><blockquote><p>按复杂度路由：分类用小模型，推理用大模型；置信度/失败率动态调整，平衡成本质量。</p></blockquote><p><strong>25. 如何降本？</strong></p><blockquote><p>语义缓存、小模型路由、上下文压缩、批处理/异步。</p></blockquote><p><strong>26. 可观测比普通应用多了什么？</strong></p><blockquote><p>token 用量、延迟分解（首 token/总）、幻觉率、评测分、Prompt 版本、降级次数、成本。</p></blockquote><h2 id="六、场景题" tabindex="-1">六、场景题 <a class="header-anchor" href="#六、场景题" aria-label="Permalink to &quot;六、场景题&quot;">​</a></h2><p><strong>27. 设计一个企业客服 Agent？</strong></p><blockquote><p>意图识别→RAG 查知识库→ReAct 调用工单/查询工具→记忆用户上下文→人工兜底。重排+溯源+降级+权限。</p></blockquote><p><strong>28. 长对话 Agent 怎么不丢信息？</strong></p><blockquote><p>滑窗+摘要压缩+长期记忆检索；关键事实显式提取存库，按需拉取。</p></blockquote><p><strong>29. Agent 怎么保证回答可靠？</strong></p><blockquote><p>多步校验节点、工具结果验证、关键动作人工确认、评测闭环、不轻信单步输出。</p></blockquote><p><strong>30. 自研核心循环还是用框架？</strong></p><blockquote><p>原型用框架快；生产多数自研（ReAct 几十行）更可控/好调试/成本低。</p></blockquote><p><strong>31. 如何评估一个 Agent 系统？</strong></p><blockquote><p>单工具（正确率）、轨迹（合理性）、结果（成功率/LLM-Judge）、系统（延迟/成本/可靠），基准 AgentBench/WebArena/GAIA。</p></blockquote><hr><p>➡️ 返回：<a href="./../面试真题集/README">面试真题集 README</a></p>',73)])])}const k=t(r,[["render",a]]);export{q as __pageData,k as default};
